INSERT INTO dica (titulo, descricao, id_granja) VALUES 
('Manejo de Névoa e Exaustores', 'Em dias quentes com umidade acima de 70%, ativar o sistema de nebulização em ciclos intercalados de 2 minutos.',1),
('Controle de Umidade na Cama', 'Mantenha a umidade do galpão entre 50% e 70% nos primeiros 7 dias de vida do lote.',2),
('Ajuste de Bebedouros Nipple', 'Verifique a altura dos nipples diariamente; a base deve estar na altura do dorso das aves.', 3),
('Sanitização pós-lote (Cascudo)', 'Faça o cascudamento e aplicação de inseticida no aviário imediatamente após a saída das aves.', 4),
('Ventilação Mínima em Inverno', 'Calcule a ventilação mínima baseada estritamente na biomassa total para remover umidade sem gelar o galpão.',5),
('Prevenção de Fungos em Ração', 'Evite o acúmulo de ração nos cantos dos comedouros automáticos para impedir proliferação de micotoxinas.',6),
('Monitoramento do pH da Água', 'Monitore o pH da água de bebida semanalmente, mantendo-o idealmente no intervalo entre 6.0 e 6.8.',7),
('Temperatura de Alojamento', 'Ganta temperatura de piso de 32°C e ar em 33°C no momento da recepção das pintainhas.',8),
('Biosseguridade em Veículos', 'Mantenha o arco de desinfecção operando com pressão adequada em 100% dos caminhões de ração.', 9),
('Densidade Máxima por m²', 'Não ultrapasse o limite de 39 kg/m² recomendado para galpões de ventilação positiva.',10),
('Programa de Luz Noturna', 'Respeite rigorosamente o programa de escuro de 6 horas para desenvolvimento imunológico e descanso.', 11),
('Manejo de Enchimento de Cama', 'Faça a reviração manual da cama de frango nos pontos abaixo dos nipples para evitar cascão.', 12),
('Sanitização de Tubulações (Flushing)', 'Faça flushing com solução de peróxido de hidrogênio nas tubulações de água no vazio sanitário.', 13),
('Velocidade do Ar em Túnel', 'Ajuste a velocidade do ar nos túneis de vento para no mínimo 2.5 m/s em dias de calor extremo.',14),
('Pesagem Semanal de Amostragem', 'Pese no mínimo 1% do lote em pontos aleatórios do galpão sempre no mesmo horário da manhã.', 15),
('Manutenção Preventiva do Gerador', 'Teste o gerador com carga real por 15 minutos ao menos uma vez por semana.', 16),
('Controle de Vetores (Moscas)', 'Utilize larvicidas na cama seca e iscas adulticidas no perímetro externo das instalações.', 17),
('Cadeia de Frio de Vacinas', 'Verifique a temperatura do termômetro de máxima e mínima da geladeira de vacinas (2°C a 8°C).', 18),
('Limpeza e Esgotamento de Silos', 'Realize o esgotamento completo e lavagem interna dos silos de ração a cada dois lotes.',  19),
('Inspeção de Cortinas Laterais', 'Cheque o estado das catracas, cordas e motores das cortinas antes do início de cada lote.', 20),
('Monitoramento de Gás Amônia', 'Utilize fitas reagentes ou medidores digitais para garantir amônia abaixo de 20 ppm.', 21),
('Destinação Sanitária de Carcaças', 'Mantenha a composteira de carcaças abastecida com maravalha na proporção de 2:1 para evitar odores.',22),
('Calibragem de Pratos Comedouros', 'Ajuste a vazão dos pratos na fase de terminação para evitar derrame de ração na cama.', 23),
('Estímulo Inicial de Consumo', 'Intensifique o programa de luz nas primeiras 48 horas para que 95% do lote encontre água e ração.', 24),
('Rodízio de Raticidas', 'Alterne o princípio ativo das iscas raticidas a cada 6 meses para evitar resistência dos roedores.',25),
('Remoção de Biofilme', 'Utilize desincrustantes ácidos alternados com alcalinos nas linhas de bebida entre lotes.', 26),
('Termografia em Quadros Elétricos', 'Utilize câmera termográfica para detectar pontos de aquecimento nos disjuntores dos exaustores.', 27),
('Tensão de Correias de Exaustor', 'Verifique o alinhamento das polias e a tensão das correias para evitar perda de rotação.', 28),
('Suplementação de Eletrólitos', 'Adicione eletrólitos e vitamina C na água de bebida 12 horas antes de ondas de calor previstas.', 29),
('Curva de Consumo Hidro-Alimentar', 'Compare a proporção diária de água/ração (deve ser aproximadamente 1.8 a 2.0 litros por kg).', 30);
